'use client'

import './globals.css'
import { ReactNode, useMemo } from 'react'
import { Toaster } from 'react-hot-toast'
import { AdminAuthProvider } from '@/contexts/AdminAuthContext'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { Geist, Geist_Mono } from 'next/font/google'
import { Sidebar } from '@/components/adminPanel/Sidebar'
import { usePathname } from 'next/navigation'
import clsx from 'clsx'

// Fonts
const geistSans = Geist({ variable: '--font-geist-sans', subsets: ['latin'] })
const geistMono = Geist_Mono({ variable: '--font-geist-mono', subsets: ['latin'] })

const queryClient = new QueryClient()

export default function RootLayout({ children }: { children: ReactNode }) {
  const pathname = usePathname()

  // Routes où l’on cache la sidebar
  const hideSidebarOn = useMemo(() => ['/login'], [])
  const showSidebar = useMemo(
    () => !hideSidebarOn.some((r) => pathname === r || pathname?.startsWith(`${r}/`)),
    [pathname, hideSidebarOn]
  )

  return (
    <html lang="fr">
      <body className={`${geistSans.variable} ${geistMono.variable} bg-gray-50 text-black antialiased`}>
        <QueryClientProvider client={queryClient}>
          <AdminAuthProvider>
            <div className="flex min-h-screen">
              {showSidebar && <Sidebar />}
              <main
                className={clsx(
                  'flex-1 p-6',
                  showSidebar && 'md:ml-64'
                )}
              >
                {children}
              </main>
            </div>
            <Toaster position="top-right" />
          </AdminAuthProvider>
        </QueryClientProvider>
      </body>
    </html>
  )
}
